/**
 * GIF system for No Trace.
 *
 * Works with ZERO configuration:
 * - 27 built-in animated GIFs in `public/gifs/` (15 icons + 12 text
 *   reactions), generated by `scripts/make-gifs.sh` and
 *   `scripts/generate-gifs.sh`. Fully offline.
 * - 21 curated real GIFs served directly from Giphy's CDN
 *   (`https://i.giphy.com/<id>.gif`). These are plain image URLs, so they
 *   need no API key. Every ID in the list was verified to return a real
 *   GIF (not the "not found" placeholder).
 *
 * Message formats:
 * - `gif:<local-id>`            local pack (allow-listed)
 * - `gif:https://...`           remote GIF (validated host / extension)
 * - optional caption after `\n`
 *
 * If `GIPHY_API_KEY` is configured, `/api/gifs` also proxies live
 * trending/search results from GIPHY. Otherwise it serves the curated
 * pack (filtered when `q` is present).
 */

export type Gif = {
  id: string;
  label: string;
  src: string;
};

export type RemoteGif = {
  id: string;
  label: string;
  url: string;
  preview: string;
  tags: string[];
};

const make = (id: string, label: string): Gif => ({
  id,
  label,
  src: `/gifs/${id}.gif`,
});

