const BY_ID = new Map(GIFS.map((gif) => [gif.id, gif]));

export const GIF_PREFIX = "gif:";
export const GIF_IDS = GIFS.map((gif) => gif.id);

/** Hosts allowed for `gif:https://...` remote messages. */
export const REMOTE_GIF_HOSTS = [
  "i.giphy.com",
  "media.giphy.com",
  "media0.giphy.com",
  "media1.giphy.com",
  "media2.giphy.com",
  "media3.giphy.com",
  "media4.giphy.com",
  "giphy.com",
  "media.tenor.com",
  "c.tenor.com",
  "tenor.com",
  "media.klippy.com",
  "cdn.klippy.com",
] as const;

const REMOTE_HOST_SET = new Set<string>(REMOTE_GIF_HOSTS);

/** Max length for a remote GIF URL inside a message. */
export const MAX_REMOTE_GIF_URL_LEN = 500;

export function getGif(id: string): Gif | null {
  return BY_ID.get(id.trim()) ?? null;
}

export function isGifContent(content: string) {
  return content.startsWith(GIF_PREFIX);
}

/** Checks that a remote GIF URL is safe to store and render. */
export function isRemoteGifUrl(raw: string): boolean {
  const value = raw.trim();
  if (!value.startsWith("https://")) return false;
  if (value.length > MAX_REMOTE_GIF_URL_LEN) return false;
  if (/[\s"'<>]/.test(value)) return false;
  let parsed: URL;
  try {
    parsed = new URL(value);
  } catch {
    return false;
  }
  if (parsed.protocol !== "https:") return false;
  const host = parsed.hostname.toLowerCase();
  const knownHost = REMOTE_HOST_SET.has(host) || host.endsWith(".giphy.com") || host.endsWith(".tenor.com");
  // Known GIF CDNs: any path is fine (they serve GIFs at extensionless URLs too).
  if (knownHost) return true;
  // Unknown hosts: only direct image files.
  return /\.(gif|png|jpe?g|webp)(\?[^]*)?$/i.test(parsed.pathname + parsed.search);
}

export type ParsedGif = {
  /** Local pack GIF (when the id belongs to the bundled pack). */
  gif: Gif | null;
  /** Remote GIF URL (when `gif:https://...` passes validation). */
  remoteUrl: string | null;
  /** Optional caption after the first newline. */
  text: string;
};

/** Parses `gif:<id>` and `gif:<https-url>`, with optional `\n` caption. */
export function parseGif(content: string): ParsedGif {
  if (!isGifContent(content)) return { gif: null, remoteUrl: null, text: content };
  const newline = content.indexOf("\n");
  const head =
    newline === -1 ? content.slice(GIF_PREFIX.length) : content.slice(GIF_PREFIX.length, newline);
  const text = newline === -1 ? "" : content.slice(newline + 1);
  const id = head.trim();
  if (!id) return { gif: null, remoteUrl: null, text };
  const local = getGif(id);
  if (local) return { gif: local, remoteUrl: null, text };
  if (id.startsWith("https://") && isRemoteGifUrl(id)) {
    return { gif: null, remoteUrl: id, text };
  }
  return { gif: null, remoteUrl: null, text };
}

export function isValidGifContent(content: string): boolean {
  if (!isGifContent(content)) return false;
  if (content.length > MAX_REMOTE_GIF_URL_LEN + 200) return false;
  const parsed = parseGif(content);
  if (parsed.text.length > 500) return false;
  return parsed.gif !== null || parsed.remoteUrl !== null;
}

export const GIF_PATTERN = new RegExp(`^${GIF_PREFIX}[^\\n]{1,512}(\\n[\\s\\S]{0,500})?$`);

function normalize(text: string): string {
  return text
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

/** Searches the curated remote pack by label/tags (accent-insensitive). */
export function searchRemoteGifs(query: string, limit = 18): RemoteGif[] {
  const q = normalize(query.trim());
  if (!q) return REMOTE_GIFS.slice(0, limit);
  const words = q.split(/\s+/).filter(Boolean);
  const scored: { gif: RemoteGif; score: number }[] = [];
  for (const gif of REMOTE_GIFS) {
    const hay = normalize(`${gif.label} ${gif.tags.join(" ")}`);
    let score = 0;
    for (const word of words) {
      if (normalize(gif.label).includes(word)) score += 3;
      else if (gif.tags.some((tag) => normalize(tag).includes(word))) score += 2;
      else if (hay.includes(word)) score += 1;
      else {
        score = -1;
        break;
      }
    }
    if (score >= 0) scored.push({ gif, score });
  }
  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, limit).map((entry) => entry.gif);
}

/** Searches the local pack by label (accent-insensitive). */
export function searchLocalGifs(query: string): Gif[] {
  const q = normalize(query.trim());
  if (!q) return GIFS;
  return GIFS.filter((gif) => normalize(gif.label).includes(q) || normalize(gif.id).includes(q));
}
